### Flutter Map Interaction Configuration

Source: https://context7.com/fleaflet/flutter_map/llms.txt

Configures gesture recognition and map interactions in flutter_map. It allows disabling/enabling specific flags, adjusting gesture thresholds like rotation and pinch zoom, and setting parameters for scroll wheel velocity and double-tap zoom.

```dart
import 'package:flutter/material.dart';
import 'package:flutter_map/flutter_map.dart';
import 'package:latlong2/latlong.dart';

class InteractionConfigExample extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: FlutterMap(
        options: MapOptions(
          initialCenter: LatLng(51.5, -0.09),
          initialZoom: 5.0,
          minZoom: 3.0,
          maxZoom: 18.0,
          // Fine-tune interaction behavior
          interactionOptions: InteractionOptions(
            // Disable specific interactions
            flags: InteractiveFlag.all & ~InteractiveFlag.rotate,
            // Or enable only specific interactions
            // flags: InteractiveFlag.drag | InteractiveFlag.pinchZoom,

            // Gesture thresholds
            rotationThreshold: 20.0,  // Degrees before rotation starts
            pinchZoomThreshold: 0.5,  // Minimum pinch distance
            pinchMoveThreshold: 40.0,  // Pixels before pinch-move starts

            // Scroll wheel configuration
            scrollWheelVelocity: 0.005,  // Zoom speed for mouse wheel

            // Double-tap zoom
            doubleTapZoomDuration: Duration(milliseconds: 200),
            doubleTapZoomCurve: Curves.fastOutSlowIn,
          ),
        ),
        children: [
          TileLayer(
            urlTemplate: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
            userAgentPackageName: 'com.example.app',
          ),
        ],
      ),
    );
  }
}

// Example: Read-only map (no interactions)
class ReadOnlyMapExample extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return FlutterMap(
      options: MapOptions(
        initialCenter: LatLng(51.5, -0.09),
        initialZoom: 10.0,
        interactionOptions: InteractionOptions(
          flags: InteractiveFlag.none,  // Disable all interactions
        ),
      ),
      children: [
        TileLayer(
          urlTemplate: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
          userAgentPackageName: 'com.example.app',
        ),
      ],
    );
  }
}

```

