### Configure Flutter Map Tile Layer

Source: https://context7.com/fleaflet/flutter_map/llms.txt

Configures a standard TileLayer in Flutter Map with URL templates, fallbacks, subdomains, zoom levels, performance settings, retina support, API options, display animations, error handling, user agent, and custom tile providers.

```dart
import 'package:flutter/material.dart';
import 'package:flutter_map/flutter_map.dart';
import 'package:latlong2/latlong.dart';

class TileLayerConfigExample extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: FlutterMap(
        options: MapOptions(
          initialCenter: LatLng(51.5, -0.09),
          initialZoom: 5.0,
        ),
        children: [
          TileLayer(
            // URL template with placeholders
            urlTemplate: 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',

            // Fallback URL if primary fails
            fallbackUrl: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',

            // Subdomain rotation for load balancing
            subdomains: ['a', 'b', 'c'],

            // Tile dimensions and zoom levels
            tileDimension: 256,
            minZoom: 0,
            maxZoom: 18,
            minNativeZoom: 0,
            maxNativeZoom: 19,

            // Performance settings
            keepBuffer: 2,  // Keep tiles outside viewport
            panBuffer: 1,   // Load tiles outside viewport

            // Retina/HiDPI support
            retinaMode: true,

            // Additional URL parameters
            additionalOptions: {
              'apikey': 'your-api-key',
              'style': 'streets',
            },

            // Tile display animation
            tileDisplay: TileDisplay.fadeIn(
              duration: Duration(milliseconds: 300),
            ),
            // Or instant display:
            // tileDisplay: TileDisplay.instantaneous(),

            // Error handling
            errorImage: AssetImage('assets/tile_error.png'),
            errorTileCallback: (tile, error, stackTrace) {
              print('Tile load error: ${tile.coordinates} - $error');
            },

            // User agent (required for some tile servers)
            userAgentPackageName: 'com.example.app',

            // Custom tile provider
            tileProvider: NetworkTileProvider(),
          ),
        ],
      ),
    );
  }
}

```

### Create Interactive Map Markers in Dart

Source: https://context7.com/fleaflet/flutter_map/llms.txt

Illustrates how to create interactive markers on a map using `MarkerLayer`. Each marker can display custom widgets, respond to tap events (showing a SnackBar), and be configured with properties like width, height, and alignment. The example also includes functionality to add new markers via map taps. This requires the `flutter_map` and `latlong2` packages.

```dart
import 'package:flutter/material.dart';
import 'package:flutter_map/flutter_map.dart';
import 'package:latlong2/latlong.dart';

class MarkersExample extends StatefulWidget {
  @override
  State<MarkersExample> createState() => _MarkersExampleState();
}

class _MarkersExampleState extends State<MarkersExample> {
  List<Marker> markers = [];

  Marker _buildMarker(LatLng point, String label) {
    return Marker(
      point: point,
      width: 80,
      height: 80,
      alignment: Alignment.topCenter,
      child: GestureDetector(
        onTap: () {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text('Tapped marker: $label'),
              duration: Duration(seconds: 1),
            ),
          );
        },
        child: Column(
          children: [
            Icon(Icons.location_pin, size: 50, color: Colors.red),
            Text(label, style: TextStyle(fontSize: 12, fontWeight: FontWeight.bold)),
          ],
        ),
      ),
    );
  }

  @override
  void initState() {
    super.initState();
    markers = [
      _buildMarker(LatLng(51.5, -0.09), 'London'),
      _buildMarker(LatLng(48.8566, 2.3522), 'Paris'),
      _buildMarker(LatLng(53.3498, -6.2603), 'Dublin'),
    ];
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: FlutterMap(
        options: MapOptions(
          initialCenter: LatLng(51.5, -0.09),
          initialZoom: 5.0,
          onTap: (tapPosition, latLng) {
            setState(() {
              markers.add(_buildMarker(latLng, 'New ${markers.length + 1}'));
            });
          },
        ),
        children: [
          TileLayer(
            urlTemplate: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
            userAgentPackageName: 'com.example.app',
          ),
          MarkerLayer(
            markers: markers,
            rotate: false,  // Set to true to rotate markers with map
          ),
        ],
      ),
    );
  }
}

```

