### Compose Multiple Layers in FlutterMap (Dart)

Source: https://context7.com/fleaflet/flutter_map/llms.txt

Combines various FlutterMap layers including TileLayer, PolygonLayer, CircleLayer, PolylineLayer, MarkerLayer, and RichAttributionWidget. This example requires the flutter_map and latlong2 packages. It takes MapOptions for map configuration and returns a Scaffold with the FlutterMap widget.

```dart
import 'package:flutter/material.dart';
import 'package:flutter_map/flutter_map.dart';
import 'package:latlong2/latlong.dart';

class MultiLayerExample extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: FlutterMap(
        options: MapOptions(
          initialCenter: LatLng(51.5, -0.09),
          initialZoom: 8.0,
        ),
        children: [
          // Base tile layer
          TileLayer(
            urlTemplate: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
            userAgentPackageName: 'com.example.app',
          ),

          // Polygon layer (drawn first, appears behind)
          PolygonLayer(
            polygons: [
              Polygon(
                points: [
                  LatLng(51.5, -0.5),
                  LatLng(51.5, 0.3),
                  LatLng(52.0, 0.3),
                  LatLng(52.0, -0.5),
                ],
                color: Colors.blue.withOpacity(0.2),
                borderColor: Colors.blue,
                borderStrokeWidth: 2,
                label: 'Zone A',
              ),
            ],
          ),

          // Circle layer
          CircleLayer(
            circles: [
              CircleMarker(
                point: LatLng(51.7, -0.1),
                radius: 5000,
                useRadiusInMeter: true,
                color: Colors.red.withOpacity(0.3),
                borderStrokeWidth: 2,
                borderColor: Colors.red,
              ),
            ],
          ),

          // Polyline layer
          PolylineLayer(
            polylines: [
              Polyline(
                points: [
                  LatLng(51.5, -0.09),
                  LatLng(51.7, -0.1),
                  LatLng(51.9, 0.1),
                ],
                strokeWidth: 4,
                color: Colors.green,
              ),
            ],
          ),

          // Marker layer (drawn last, appears on top)
          MarkerLayer(
            markers: [
              Marker(
                point: LatLng(51.5, -0.09),
                width: 80,
                height: 80,
                child: Icon(Icons.location_city, size: 50, color: Colors.purple),
              ),
              Marker(
                point: LatLng(51.9, 0.1),
                width: 80,
                height: 80,
                child: Icon(Icons.location_pin, size: 50, color: Colors.orange),
              ),
            ],
          ),

          // Attribution widget
          RichAttributionWidget(
            attributions: [
              TextSourceAttribution(
                'OpenStreetMap contributors',
                onTap: () => print('Tapped attribution'),
              ),
            ],
          ),
        ],
      ),
    );
  }
}

```

