### Draw Circle Markers with Flutter Map

Source: https://context7.com/fleaflet/flutter_map/llms.txt

Renders circular markers on the map with support for pixel or meter-based radius. Requires flutter/material, flutter_map, and latlong2 packages. Input is a list of CircleMarker objects.

```dart
import 'package:flutter/material.dart';
import 'package:flutter_map/flutter_map.dart';
import 'package:latlong2/latlong.dart';

class CircleExample extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: FlutterMap(
        options: MapOptions(
          initialCenter: LatLng(51.5, -0.09),
          initialZoom: 7.0,
        ),
        children: [
          TileLayer(
            urlTemplate: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
            userAgentPackageName: 'com.example.app',
          ),
          CircleLayer(
            circles: [
              // Circle with pixel radius
              CircleMarker(
                point: LatLng(51.5, -0.09),
                radius: 50,
                color: Colors.blue.withOpacity(0.3),
                borderStrokeWidth: 3.0,
                borderColor: Colors.blue,
              ),
              // Circle with meter-based radius
              CircleMarker(
                point: LatLng(52.0, 0.5),
                radius: 25000,  // 25km
                useRadiusInMeter: true,
                color: Colors.red.withOpacity(0.2),
                borderStrokeWidth: 2.0,
                borderColor: Colors.red,
              ),
              // Small marker circle
              CircleMarker(
                point: LatLng(51.3, 0.2),
                radius: 10,
                color: Colors.green,
              ),
            ],
          ),
        ],
      ),
    );
  }
}
```

