### Draw Polygons with Flutter Map

Source: https://context7.com/fleaflet/flutter_map/llms.txt

Renders filled polygons with options for borders, labels, and holes. Requires flutter/material, flutter_map, and latlong2 packages. Input is a list of Polygon objects.

```dart
import 'package:flutter/material.dart';
import 'package:flutter_map/flutter_map.dart';
import 'package:latlong2/latlong.dart';

class PolygonExample extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: FlutterMap(
        options: MapOptions(
          initialCenter: LatLng(51.5, -0.09),
          initialZoom: 7.0,
        ),
        children: [
          TileLayer(
            urlTemplate: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
            userAgentPackageName: 'com.example.app',
          ),
          PolygonLayer(
            polygons: [
              // Simple filled polygon
              Polygon(
                points: [
                  LatLng(51.5, -0.09),
                  LatLng(51.5, 0.5),
                  LatLng(52.0, 0.5),
                  LatLng(52.0, -0.09),
                ],
                color: Colors.blue.withOpacity(0.3),
                borderColor: Colors.blue,
                borderStrokeWidth: 2.0,
                isFilled: true,
              ),
              // Polygon with label
              Polygon(
                points: [
                  LatLng(51.0, -0.09),
                  LatLng(51.0, 0.5),
                  LatLng(51.3, 0.5),
                  LatLng(51.3, -0.09),
                ],
                color: Colors.red.withOpacity(0.3),
                borderColor: Colors.red,
                borderStrokeWidth: 2.0,
                label: 'Region A',
                labelStyle: TextStyle(
                  color: Colors.white,
                  fontWeight: FontWeight.bold,
                  fontSize: 16,
                ),
              ),
              // Polygon with hole
              Polygon(
                points: [
                  LatLng(50.5, 1.0),
                  LatLng(50.5, 2.0),
                  LatLng(51.0, 2.0),
                  LatLng(51.0, 1.0),
                ],
                holePointsList: [
                  [
                    LatLng(50.6, 1.2),
                    LatLng(50.6, 1.8),
                    LatLng(50.9, 1.8),
                    LatLng(50.9, 1.2),
                  ],
                ],
                color: Colors.green.withOpacity(0.3),
                borderColor: Colors.green,
                borderStrokeWidth: 2.0,
              ),
            ],
          ),
        ],
      ),
    );
  }
}
```

