### Drawing Polylines with Flutter Map

Source: https://context7.com/fleaflet/flutter_map/llms.txt

This Dart code snippet illustrates the usage of the `PolylineLayer` from the `flutter_map` package to render various types of polylines on a map. It shows how to define points, stroke width, colors, gradients, borders, and stroke patterns like dashed and dotted. The example also includes a polyline with `useStrokeWidthInMeter` set to true for meter-based width.

```dart
import 'package:flutter/material.dart';
import 'package:flutter_map/flutter_map.dart';
import 'package:latlong2/latlong.dart';

class PolylineExample extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: FlutterMap(
        options: MapOptions(
          initialCenter: LatLng(51.5, -0.09),
          initialZoom: 5.0,
        ),
        children: [
          TileLayer(
            urlTemplate: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
            userAgentPackageName: 'com.example.app',
          ),
          PolylineLayer(
            polylines: [
              // Solid line
              Polyline(
                points: [
                  LatLng(51.5, -0.09),
                  LatLng(53.3498, -6.2603),
                  LatLng(48.8566, 2.3522),
                ],
                strokeWidth: 4.0,
                color: Colors.blue,
              ),
              // Gradient line
              Polyline(
                points: [
                  LatLng(51.74904, -10.32324),
                  LatLng(54.3498, -6.2603),
                  LatLng(52.8566, 2.3522),
                ],
                strokeWidth: 4.0,
                gradientColors: [Colors.red, Colors.yellow, Colors.green],
              ),
              // Bordered line
              Polyline(
                points: [
                  LatLng(50.5, -0.09),
                  LatLng(51.3498, 6.2603),
                  LatLng(53.8566, 2.3522),
                ],
                strokeWidth: 10.0,
                color: Colors.blue.withOpacity(0.6),
                borderStrokeWidth: 10.0,
                borderColor: Colors.red.withOpacity(0.4),
              ),
              // Dashed line
              Polyline(
                points: [
                  LatLng(48.8567, 2.3519),
                  LatLng(45.7256, 5.0811),
                  LatLng(43.6958, 7.2714),
                ],
                strokeWidth: 6.0,
                color: Colors.green[900]!,
                pattern: StrokePattern.dashed(segments: [50, 20, 30, 20]),
              ),
              // Dotted line
              Polyline(
                points: [
                  LatLng(43.864797, 11.7112939),
                  LatLng(36.7948545, 10.2256785),
                  LatLng(35.566530, 5.584283),
                ],
                strokeWidth: 10.0,
                color: Colors.orange,
                pattern: StrokePattern.dotted(spacingFactor: 3),
              ),
              // Line with meter-based width
              Polyline(
                points: [
                  LatLng(48.5, -3.09),
                  LatLng(47.3498, -9.2603),
                  LatLng(43.8566, -1.3522),
                ],
                strokeWidth: 16000,
                color: Colors.pink,
                useStrokeWidthInMeter: true,
              ),
            ],
          ),
        ],
      ),
    );
  }
}
```

### Configure Flutter Map Tile Layer

Source: https://context7.com/fleaflet/flutter_map/llms.txt

Configures a standard TileLayer in Flutter Map with URL templates, fallbacks, subdomains, zoom levels, performance settings, retina support, API options, display animations, error handling, user agent, and custom tile providers.

```dart
import 'package:flutter/material.dart';
import 'package:flutter_map/flutter_map.dart';
import 'package:latlong2/latlong.dart';

class TileLayerConfigExample extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: FlutterMap(
        options: MapOptions(
          initialCenter: LatLng(51.5, -0.09),
          initialZoom: 5.0,
        ),
        children: [
          TileLayer(
            // URL template with placeholders
            urlTemplate: 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',

            // Fallback URL if primary fails
            fallbackUrl: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',

            // Subdomain rotation for load balancing
            subdomains: ['a', 'b', 'c'],

            // Tile dimensions and zoom levels
            tileDimension: 256,
            minZoom: 0,
            maxZoom: 18,
            minNativeZoom: 0,
            maxNativeZoom: 19,

            // Performance settings
            keepBuffer: 2,  // Keep tiles outside viewport
            panBuffer: 1,   // Load tiles outside viewport

            // Retina/HiDPI support
            retinaMode: true,

            // Additional URL parameters
            additionalOptions: {
              'apikey': 'your-api-key',
              'style': 'streets',
            },

            // Tile display animation
            tileDisplay: TileDisplay.fadeIn(
              duration: Duration(milliseconds: 300),
            ),
            // Or instant display:
            // tileDisplay: TileDisplay.instantaneous(),

            // Error handling
            errorImage: AssetImage('assets/tile_error.png'),
            errorTileCallback: (tile, error, stackTrace) {
              print('Tile load error: ${tile.coordinates} - $error');
            },

            // User agent (required for some tile servers)
            userAgentPackageName: 'com.example.app',

            // Custom tile provider
            tileProvider: NetworkTileProvider(),
          ),
        ],
      ),
    );
  }
}

