### Flutter Map Coordinate Conversion and Camera Access (Dart)

Source: https://context7.com/fleaflet/flutter_map/llms.txt

This Dart code snippet demonstrates accessing the current camera state (center, zoom, rotation, bounds) of a FlutterMap. It also shows how to convert geographic LatLng coordinates to screen offsets and screen offsets back to LatLng coordinates using the MapController. Requires the flutter_map and latlong2 packages.

```dart
import 'package:flutter/material.dart';
import 'package:flutter_map/flutter_map.dart';
import 'package:latlong2/latlong.dart';

class CoordinateConversionExample extends StatefulWidget {
  @override
  State<CoordinateConversionExample> createState() => _CoordinateConversionExampleState();
}

class _CoordinateConversionExampleState extends State<CoordinateConversionExample> {
  final MapController _mapController = MapController();
  String _info = '';

  void _demonstrateConversions() {
    final camera = _mapController.camera;

    // Get current camera state
    final center = camera.center;
    final zoom = camera.zoom;
    final rotation = camera.rotation;
    final bounds = camera.visibleBounds;

    // Convert LatLng to screen offset
    final londonLatLng = LatLng(51.5, -0.09);
    final screenOffset = camera.latLngToScreenOffset(londonLatLng);

    // Convert screen offset back to LatLng
    final convertedLatLng = camera.screenOffsetToLatLng(screenOffset);

    setState(() {
      _info = 'Camera Info:\n'
          'Center: ${center.latitude.toStringAsFixed(4)}, ${center.longitude.toStringAsFixed(4)}
'
          'Zoom: ${zoom.toStringAsFixed(2)}
'
          'Rotation: ${rotation.toStringAsFixed(2)}°
'
          'Bounds: N:${bounds.north.toStringAsFixed(2)}, '
          'S:${bounds.south.toStringAsFixed(2)}, '
          'E:${bounds.east.toStringAsFixed(2)}, '
          'W:${bounds.west.toStringAsFixed(2)}

'
          'London LatLng: $londonLatLng
'
          'Screen Offset: (${screenOffset.dx.toStringAsFixed(1)}, ${screenOffset.dy.toStringAsFixed(1)})
'
          'Back to LatLng: ${convertedLatLng.latitude.toStringAsFixed(4)}, '
          '${convertedLatLng.longitude.toStringAsFixed(4)}';
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Column(
        children: [
          Container(
            padding: EdgeInsets.all(16),
            color: Colors.grey[200],
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                ElevatedButton(
                  onPressed: _demonstrateConversions,
                  child: Text('Get Camera Info'),
                ),
                SizedBox(height: 8),
                Text(_info, style: TextStyle(fontSize: 11)),
              ],
            ),
          ),
          Expanded(
            child: FlutterMap(
              mapController: _mapController,
              options: MapOptions(
                initialCenter: LatLng(51.5, -0.09),
                initialZoom: 5.0,
              ),
              children: [
                TileLayer(
                  urlTemplate: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
                  userAgentPackageName: 'com.example.app',
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

```

