import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:flutter_map/flutter_map.dart';
import 'package:flutter_map_location_marker/flutter_map_location_marker.dart';
import 'package:latlong2/latlong.dart';
import 'package:telectric/cubit/station_cubit.dart';
import 'package:telectric/cubit/station_state.dart';
import 'package:telectric/models/charging_station.dart';
import 'package:telectric/ui/station_detail_sheet.dart';
import 'package:telectric/ui/widgets/api_call_counter.dart';

class MapScreen extends StatefulWidget {
  const MapScreen({super.key});

  @override
  State<MapScreen> createState() => _MapScreenState();
}

class _MapScreenState extends State<MapScreen> {
  final MapController _mapController = MapController();
  bool _showSearchHere = false;
  LatLng? _lastSearchCenter;

  @override
  void initState() {
    super.initState();
    context.read<StationCubit>().loadStationsAtCurrentLocation();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: BlocConsumer<StationCubit, StationState>(
        listener: (context, state) {
          state.whenOrNull(
            loaded: (stations, selected, lat, lng, radius, count) {
              _lastSearchCenter = LatLng(lat, lng);
              _showSearchHere = false;
              _mapController.move(LatLng(lat, lng), _mapController.camera.zoom);
            },
            error: (message, _, __) {
              ScaffoldMessenger.of(context).showSnackBar(
                SnackBar(content: Text(message), backgroundColor: Colors.red),
              );
            },
          );
        },
        builder: (context, state) {
          final stations = state.maybeWhen(
            loaded: (stations, _, __, ___, ____, _____) => stations,
            orElse: () => <ChargingStation>[],
          );

          final selectedStation = state.maybeWhen(
            loaded: (_, selected, __, ___, ____, _____) => selected,
            orElse: () => null,
          );

          final isLoading = state is StationLoading;

          return Stack(
            children: [
              FlutterMap(
                mapController: _mapController,
                options: MapOptions(
                  initialCenter: const LatLng(52.0907, 5.1214),
                  initialZoom: 13.0,
                  onPositionChanged: _onPositionChanged,
                ),
                children: [
                  TileLayer(
                    urlTemplate:
                        'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
                    userAgentPackageName: 'com.example.telectric',
                  ),
                  CurrentLocationLayer(),
                  MarkerLayer(
                    markers: stations
                        .map((s) => _buildMarker(context, s))
                        .toList(),
                  ),
                ],
              ),
              // API call counter
              const Positioned(
                top: 50,
                right: 16,
                child: SafeArea(child: ApiCallCounter()),
              ),
              // Loading indicator
              if (isLoading)
                const Center(child: CircularProgressIndicator()),
              // Search this area button
              if (_showSearchHere)
                Positioned(
                  top: 100,
                  left: 0,
                  right: 0,
                  child: Center(
                    child: ElevatedButton.icon(
                      onPressed: _searchThisArea,
                      icon: const Icon(Icons.search),
                      label: const Text('Search this area'),
                    ),
                  ),
                ),
              // Station detail sheet
              if (selectedStation != null)
                Positioned(
                  bottom: 0,
                  left: 0,
                  right: 0,
                  child: StationDetailSheet(
                    station: selectedStation,
                    onClose: () =>
                        context.read<StationCubit>().clearSelection(),
                  ),
                ),
            ],
          );
        },
      ),
      floatingActionButton: Padding(
        padding: const EdgeInsets.only(bottom: 16),
        child: FloatingActionButton(
          onPressed: () =>
              context.read<StationCubit>().loadStationsAtCurrentLocation(),
          child: const Icon(Icons.my_location),
        ),
      ),
    );
  }

  Marker _buildMarker(BuildContext context, ChargingStation station) {
    return Marker(
      point: LatLng(
        station.addressInfo.latitude,
        station.addressInfo.longitude,
      ),
      width: 40,
      height: 40,
      child: GestureDetector(
        onTap: () => context.read<StationCubit>().selectStation(station),
        child: Icon(
          Icons.ev_station,
          color: Theme.of(context).colorScheme.primary,
          size: 36,
        ),
      ),
    );
  }

  void _onPositionChanged(MapCamera camera, bool hasGesture) {
    if (!hasGesture || _lastSearchCenter == null) return;

    final distance = const Distance().as(
      LengthUnit.Kilometer,
      _lastSearchCenter!,
      camera.center,
    );

    if (distance > 2 && !_showSearchHere) {
      setState(() => _showSearchHere = true);
    }
  }

  void _searchThisArea() {
    final center = _mapController.camera.center;
    context
        .read<StationCubit>()
        .loadStationsAtPosition(center.latitude, center.longitude);
    setState(() => _showSearchHere = false);
  }
}

