import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:flutter_map/flutter_map.dart';
import 'package:flutter_map_location_marker/flutter_map_location_marker.dart';
import 'package:latlong2/latlong.dart';
import 'package:telectric/cubit/station_cubit.dart';
import 'package:telectric/cubit/station_state.dart';
import 'package:telectric/models/charging_station.dart';
import 'package:telectric/ui/station_detail_sheet.dart';
import 'package:telectric/ui/widgets/api_call_counter.dart';

class MapScreen extends StatefulWidget {
  const MapScreen({super.key});

  @override
  State<MapScreen> createState() => _MapScreenState();
}

class _MapScreenState extends State<MapScreen> {
  final MapController _mapController = MapController();
  bool _showSearchHere = false;
  LatLng? _lastSearchCenter;

  @override
  void initState() {
    super.initState();
    context.read<StationCubit>().loadStationsAtCurrentLocation();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: BlocConsumer<StationCubit, StationState>(
        listener: (context, state) {
          switch (state) {
            case StationLoaded(:final searchLatitude, :final searchLongitude):
              _lastSearchCenter = LatLng(searchLatitude, searchLongitude);
              _showSearchHere = false;
              _mapController.move(
                LatLng(searchLatitude, searchLongitude),
                _mapController.camera.zoom,
              );
            case StationError(:final message):
              ScaffoldMessenger.of(context).showSnackBar(
                SnackBar(content: Text(message), backgroundColor: Colors.red),
              );
            default:
              break;
          }
        },
        builder: (context, state) {
          final stations = switch (state) {
            StationLoaded(:final stations) => stations,
            _ => <ChargingStation>[],
          };

          final selectedStation = switch (state) {
            StationLoaded(:final selectedStation) => selectedStation,
            _ => null,
          };

          final isLoading = state is StationLoading;

          return Stack(
            children: [
              FlutterMap(
                mapController: _mapController,
                options: MapOptions(
                  initialCenter: const LatLng(52.0907, 4.8214),
                  initialZoom: 13.0,
                  onPositionChanged: _onPositionChanged,
                ),
                children: [
                  TileLayer(
                    urlTemplate:
                        'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
                    userAgentPackageName: 'com.example.telectric',
                  ),
                  CurrentLocationLayer(headingStream: const Stream.empty()),
                  MarkerLayer(
                    markers: stations
                        .map((s) => _buildMarker(context, s))
                        .toList(),
                  ),
                ],
              ),
              const Positioned(
                top: 50,
                right: 16,
                child: SafeArea(child: ApiCallCounter()),
              ),
              if (isLoading) const Center(child: CircularProgressIndicator()),
              if (_showSearchHere)
                Positioned(
                  top: 100,
                  left: 0,
                  right: 0,
                  child: Center(
                    child: ElevatedButton.icon(
                      onPressed: _searchThisArea,
                      icon: const Icon(Icons.search),
                      label: const Text('Search this area'),
                    ),
                  ),
                ),
              if (selectedStation != null)
                Positioned(
                  bottom: 0,
                  left: 0,
                  right: 0,
                  child: StationDetailSheet(
                    station: selectedStation,
                    onClose: () =>
                        context.read<StationCubit>().clearSelection(),
                  ),
                ),
            ],
          );
        },
      ),
      floatingActionButton: Padding(
        padding: const EdgeInsets.only(bottom: 16),
        child: FloatingActionButton(
          onPressed: () =>
              context.read<StationCubit>().loadStationsAtCurrentLocation(),
          child: const Icon(Icons.my_location),
        ),
      ),
    );
  }

  Marker _buildMarker(BuildContext context, ChargingStation station) {
    return Marker(
      point: LatLng(
        station.addressInfo.latitude,
        station.addressInfo.longitude,
      ),
      width: 40,
      height: 40,
      child: GestureDetector(
        onTap: () => context.read<StationCubit>().selectStation(station),
        child: Icon(
          Icons.ev_station,
          color: Theme.of(context).colorScheme.primary,
          size: 36,
        ),
      ),
    );
  }

  void _onPositionChanged(MapCamera camera, bool hasGesture) {
    if (!hasGesture || _lastSearchCenter == null) return;

    final distance = const Distance().as(
      LengthUnit.Kilometer,
      _lastSearchCenter!,
      camera.center,
    );

    if (distance > 2 && !_showSearchHere) {
      setState(() => _showSearchHere = true);
    }
  }

  void _searchThisArea() {
    final center = _mapController.camera.center;
    context.read<StationCubit>().loadStationsAtPosition(
      center.latitude,
      center.longitude,
    );
    setState(() => _showSearchHere = false);
  }
}

import 'package:flutter/material.dart';
import 'package:telectric/models/charging_station.dart';

class StationDetailSheet extends StatelessWidget {
  final ChargingStation station;
  final VoidCallback onClose;

  const StationDetailSheet({
    super.key,
    required this.station,
    required this.onClose,
  });

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final address = station.addressInfo;

    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: theme.colorScheme.surface,
        borderRadius: const BorderRadius.vertical(top: Radius.circular(16)),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: 0.15),
            blurRadius: 10,
            offset: const Offset(0, -2),
          ),
        ],
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Icon(Icons.ev_station, color: theme.colorScheme.primary),
              const SizedBox(width: 8),
              Expanded(
                child: Text(
                  address.title,
                  style: theme.textTheme.titleMedium?.copyWith(
                    fontWeight: FontWeight.bold,
                  ),
                ),
              ),
              IconButton(
                icon: const Icon(Icons.close),
                onPressed: onClose,
              ),
            ],
          ),
          const SizedBox(height: 8),
          if (address.addressLine1 != null)
            _InfoRow(Icons.location_on, address.addressLine1!),
          if (address.town != null)
            _InfoRow(Icons.location_city, address.town!),
          if (address.distance != null)
            _InfoRow(
              Icons.straighten,
              '${address.distance!.toStringAsFixed(1)} km away',
            ),
          if (station.operatorInfo?.title != null)
            _InfoRow(Icons.business, station.operatorInfo!.title!),
          if (station.usageCost != null)
            _InfoRow(Icons.attach_money, station.usageCost!),
          if (station.numberOfPoints != null)
            _InfoRow(
              Icons.electrical_services,
              '${station.numberOfPoints} charging point(s)',
            ),
          if (station.connections.isNotEmpty) ...[
            const SizedBox(height: 12),
            Text(
              'Connectors',
              style: theme.textTheme.titleSmall?.copyWith(
                fontWeight: FontWeight.bold,
              ),
            ),
            const SizedBox(height: 4),
            ...station.connections.map((c) => _ConnectionTile(connection: c)),
          ],
        ],
      ),
    );
  }
}

class _InfoRow extends StatelessWidget {
  final IconData icon;
  final String text;

  const _InfoRow(this.icon, this.text);

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 2),
      child: Row(
        children: [
          Icon(icon, size: 16, color: Colors.grey[600]),
          const SizedBox(width: 8),
          Expanded(
            child: Text(text, style: Theme.of(context).textTheme.bodyMedium),
          ),
        ],
      ),
    );
  }
}

class _ConnectionTile extends StatelessWidget {
  final Connection connection;

  const _ConnectionTile({required this.connection});

  @override
  Widget build(BuildContext context) {
    final type = connection.connectionType?.title ?? 'Unknown';
    final power = connection.powerKW;
    final status = connection.statusType;
    final isOperational = status?.isOperational ?? true;

    return Container(
      margin: const EdgeInsets.symmetric(vertical: 2),
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
      decoration: BoxDecoration(
        color: isOperational
            ? Colors.green.withValues(alpha: 0.1)
            : Colors.red.withValues(alpha: 0.1),
        borderRadius: BorderRadius.circular(8),
      ),
      child: Row(
        children: [
          Icon(
            Icons.power,
            size: 16,
            color: isOperational ? Colors.green : Colors.red,
          ),
          const SizedBox(width: 8),
          Text(type),
          const Spacer(),
          if (power != null)
            Text(
              '${power.toStringAsFixed(0)} kW',
              style: const TextStyle(fontWeight: FontWeight.bold),
            ),
        ],
      ),
    );
  }
}

