    final center = _mapController.camera.center;
    final radius = _radiusFromZoom(_mapController.camera.zoom);
    context.read<StationCubit>().loadStationsAtPosition(
          center.latitude,
          center.longitude,
          radius: radius,
        );
    setState(() => _showSearchHere = false);
  }
